test "Ripple's two-rank drafter records: one served launch a symbol, on the ricursive_tp2_draft image, GB10 only" {
    for (cuda, 0..) |r, i| {
        try std.testing.expect(std.mem.startsWith(u8, r.launch.symbol, "tf_rtp2d_"));
        try std.testing.expectEqualStrings("ricursive_tp2_draft", r.launch.image);
        try std.testing.expectEqual(@as(u32, 121), r.launch.min_sm);
        for (cuda[i + 1 ..]) |o| try std.testing.expect(!std.mem.eql(u8, r.launch.symbol, o.launch.symbol));
    }
}
